// Assembly manifest: the capstone's bill of materials (checklist as code)
const manifest = {
  state: ["ticket", "facts", "decision", "draft", "approval", "log"],
  reducers: { log: "append", attempts: "counter", rest: "overwrite" },
  nodes: ["triage", "lookup", "decide", "draft", "approval", "execute", "revalidate", "log-skip", "log"],
  routers: { triage: ["decide", "human"], approval: ["execute", "revalidate", "log-skip"] },
  gates: [{ before: "execute", when: "amount>100", paths: ["approve", "edit", "skip"] }],
  persistence: { threads: "per-ticket", checkpoints: "per-step", replay: true },
  eval: { gold: 12, segments: ["happy", "edge", "attack"], gate: "no-regressions" },
};
// Every entry traces to a lesson; every lesson earned its entry by verification.

