const manifest = {
  state: ['ticket', 'facts', 'decision', 'draft', 'approval', 'log'],
  nodes: ['triage', 'lookup', 'decide', 'draft', 'approval', 'execute', 'revalidate', 'log-skip', 'log'],
  routers: { triage: ['decide', 'human'], approval: ['execute', 'revalidate', 'log-skip'] },
  gates: [{ before: 'execute', paths: ['approve', 'edit', 'skip'] }],
};
const checks = [
  ['state covers log', manifest.state.includes('log')],
  ['every router target is a node', Object.values(manifest.routers).flat().every((n) => manifest.nodes.includes(n) || n === 'human')],
  ['gate precedes execute', manifest.gates.every((g) => g.before === 'execute')],
  ['edit path tested', manifest.routers.approval.includes('revalidate')],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');
